import { Group, Mesh, Shape, ExtrudeGeometry, BoxGeometry, CircleGeometry, PointLight, Color } from 'three/webgpu';
import { MeshPhysicalNodeMaterial, MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

const INK = '#16161d';
const PAPER = '#e8ecf2';
const ACCENT = '#ff2a38';
const SURFACE = '#0b0b10';

function roundedRectShape(w, h, r) {
  const shape = new Shape();
  const x = -w / 2;
  const y = -h / 2;
  shape.moveTo(x, y + r);
  shape.lineTo(x, y + h - r);
  shape.quadraticCurveTo(x, y + h, x + r, y + h);
  shape.lineTo(x + w - r, y + h);
  shape.quadraticCurveTo(x + w, y + h, x + w, y + h - r);
  shape.lineTo(x + w, y + r);
  shape.quadraticCurveTo(x + w, y, x + w - r, y);
  shape.lineTo(x + r, y);
  shape.quadraticCurveTo(x, y, x, y + r);
  return shape;
}

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new Group();
  group.name = 'stat-tile-home';

  const colors = config?.intent?.visualSpec?.colors ?? {
    ink: INK,
    paper: PAPER,
    accent: ACCENT,
    surface: SURFACE
  };

  const cardW = 1.6;
  const cardH = 1.0;
  const cardDepth = 0.12;

  // --- depth plane 0: soft shadow / separation halo behind card ---
  const haloGeo = new CircleGeometry(1.15, 48);
  const haloMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  const haloUv = uv().sub(vec2(0.5, 0.5));
  const haloDist = haloUv.length();
  haloMat.colorNode = vec3(0.0, 0.0, 0.0);
  haloMat.opacityNode = smoothstep(0.5, 0.0, haloDist).mul(0.5);
  const halo = new Mesh(haloGeo, haloMat);
  halo.position.set(0, -0.05, -0.14);
  group.add(halo);

  // --- depth plane 1: machined surface card body ---
  const shape = roundedRectShape(cardW, cardH, 0.08);
  const extrudeSettings = {
    depth: cardDepth,
    bevelEnabled: true,
    bevelThickness: 0.02,
    bevelSize: 0.02,
    bevelSegments: 3,
    curveSegments: 8
  };
  const cardGeo = new ExtrudeGeometry(shape, extrudeSettings);
  cardGeo.center();
  const cardMat = new MeshPhysicalNodeMaterial({
    color: new Color(colors.ink ?? INK),
    roughness: 0.55,
    metalness: 0.5,
    clearcoat: 0.2,
    clearcoatRoughness: 0.35
  });
  const card = new Mesh(cardGeo, cardMat);
  card.name = 'stat-card-body';
  group.add(card);

  // --- accent edge strip (<=10% of card face) ---
  const accentGeo = new BoxGeometry(cardW * 0.55, 0.035, 0.01);
  const accentMat = new MeshStandardNodeMaterial({
    color: new Color(colors.accent ?? ACCENT),
    emissive: new Color(colors.accent ?? ACCENT),
    emissiveIntensity: 1.1,
    roughness: 0.4,
    metalness: 0.3
  });
  const accentStrip = new Mesh(accentGeo, accentMat);
  accentStrip.position.set(0, -cardH / 2 + 0.1, cardDepth / 2 + 0.006);
  group.add(accentStrip);

  // --- node-local rim/accent light (scene already provides ambient+key) ---
  const rimLight = new PointLight(new Color(colors.accent ?? ACCENT), 0.9, 4.0);
  rimLight.position.set(0.6, 0.5, 1.2);
  group.add(rimLight);

  const metalKick = new PointLight(new Color(colors.paper ?? PAPER), 0.5, 3.0);
  metalKick.position.set(-0.4, 0.3, 1.0);
  group.add(metalKick);

  // --- decorative machined gear mesh (from meshUrl) ---
  let gearRoot = null;
  let gearTween = null;
  const meshUrl = config.meshUrl;
  if (meshUrl && ctx.glbLoader) {
    ctx.glbLoader.loadGLB(meshUrl).then((gltf) => {
      const scene = gltf.scene ?? gltf;
      scene.scale.setScalar(0.34);
      scene.position.set(0.35, 0.08, cardDepth / 2 + 0.02);
      scene.rotation.z = 0.15;
      gearRoot = scene;
      group.add(gearRoot);

      gearTween = gsap.to(gearRoot.rotation, {
        z: gearRoot.rotation.z + 0.35,
        duration: 6,
        yoyo: true,
        repeat: -1,
        ease: 'sine.inOut'
      });
    }).catch(() => {});
  }

  // --- text content (verbatim only, none fabricated) ---
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textNodes = [];
  let cursorY = 0.22;
  for (const item of items) {
    const role = item.role ?? 'body';
    const isValue = role.includes('value') || role.includes('stat') || role.includes('headline');
    const fontSize = item.typography?.fontSize ?? (isValue ? 68 : 26);
    const txt = ctx.fontAtlas.createText(String(item.text ?? ''), {
      fontSize,
      color: isValue ? (colors.paper ?? PAPER) : (colors.accent ?? ACCENT),
      align: 'center'
    });
    txt.position.set(0, cursorY, cardDepth / 2 + 0.01);
    cursorY -= isValue ? 0.34 : 0.18;
    group.add(txt);
    textNodes.push(txt);
  }

  // --- cinematic primitive: parallax-scroll ---
  const primitiveHandles = [];
  const primitivesSpec = config.cinematicPrimitives ?? [];
  for (const prim of primitivesSpec) {
    const fn = ctx.primitives?.[prim.name];
    if (typeof fn === 'function') {
      const handle = fn(group, prim.params ?? {});
      primitiveHandles.push(handle);
    }
  }

  // --- interaction state ---
  const baseY = group.position.y;
  const baseScale = { x: 1, y: 1, z: 1 };
  let hoverTween = null;
  let pressTween = null;

  function onPointerOver() {
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.timeline();
    hoverTween.to(card.position, { y: 0.15, duration: 0.7, ease: 'power3.out' }, 0);
    hoverTween.to(accentStrip.material, { emissiveIntensity: 1.6, duration: 0.4, ease: 'power2.out' }, 0);
  }

  function onPointerOut() {
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.timeline();
    hoverTween.to(card.position, { y: 0.0, duration: 0.9, ease: 'power4.out' }, 0);
    hoverTween.to(accentStrip.material, { emissiveIntensity: 1.1, duration: 0.4, ease: 'power2.out' }, 0);
  }

  function onPointerDown() {
    if (pressTween) pressTween.kill();
    pressTween = gsap.to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(2)' });
  }

  function onPointerUp() {
    if (pressTween) pressTween.kill();
    pressTween = gsap.to(group.scale, { x: baseScale.x, y: baseScale.y, z: baseScale.z, duration: 0.3, ease: 'power2.out' });
  }

  function onClick() {
    ctx.emit('hub-home.select', { nodeId: config.id ?? 'stat-tile-home' });
  }

  group.userData.handlers = {
    onPointerOver,
    onPointerOut,
    onPointerDown,
    onPointerUp,
    onClick
  };

  // --- entrance ---
  group.position.y = baseY - 0.15;
  const entrance = gsap.to(group.position, {
    y: baseY,
    duration: 0.7,
    ease: 'power3.out'
  });

  group.userData.cleanup = () => {
    if (hoverTween) hoverTween.kill();
    if (pressTween) pressTween.kill();
    if (gearTween) gearTween.kill();
    if (entrance) entrance.kill();

    for (const handle of primitiveHandles) {
      handle?.timeline?.kill?.();
      handle?.cleanup?.();
    }

    cardGeo.dispose();
    cardMat.dispose();
    accentGeo.dispose();
    accentMat.dispose();
    haloGeo.dispose();
    haloMat.dispose();

    for (const t of textNodes) {
      t.geometry?.dispose?.();
      t.material?.dispose?.();
    }

    if (gearRoot) {
      gearRoot.traverse((child) => {
        if (child.geometry) child.geometry.dispose();
        if (child.material) {
          const mats = Array.isArray(child.material) ? child.material : [child.material];
          mats.forEach((m) => m.dispose?.());
        }
      });
    }
  };

  return group;
}
